window.docContents[253].resolve({"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Section-2___11___-Tensor-products-___-heading-and-introduction/#Chapter2___Discussion_2___11_heading":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.11. Tensor products\u0009Section 2.11: Tensor products — heading and introduction","header":"Section 2.11: Tensor products — heading and introduction","id":"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Section-2___11___-Tensor-products-___-heading-and-introduction/#Chapter2___Discussion_2___11_heading"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Section-2___9___-Lie-algebras-___-heading-and-skew-symmetric-bilinear-map/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___9___-Lie-algebras--Section-2___9___-Lie-algebras-___-heading-and-skew-symmetric-bilinear-map":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.9. Lie algebras","header":"Section 2.9: Lie algebras — heading and skew-symmetric bilinear map","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Section-2___9___-Lie-algebras-___-heading-and-skew-symmetric-bilinear-map/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___9___-Lie-algebras--Section-2___9___-Lie-algebras-___-heading-and-skew-symmetric-bilinear-map"},"/3___-General-results-of-representation-theory/3___9___-Problems/Section-3___9___-Problems-___-heading/#Chapter3___Introduction_to_3___9":{"contents":"\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.9. Problems\u0009Section 3.9: Problems — heading","header":"Section 3.9: Problems — heading","id":"/3___-General-results-of-representation-theory/3___9___-Problems/Section-3___9___-Problems-___-heading/#Chapter3___Introduction_to_3___9"},"/4___-Representations-of-finite-groups___-Basic-results/4___6___-Unitary-representations___-Another-proof-of-Maschke___s-theorem-for-complex-representations/Unitary-representations-are-completely-reducible/#Chapter4___Theorem4___6___3":{"contents":"Theorem 4.6.3. A finite dimensional unitary representation V of any group G is completely reducible.\n\nProof. Let W be a subrepresentation of V. Let W^\\perp be the orthogonal complement of W in V under the Hermitian inner product. Then W^\\perp is a subrepresentation of V, and V = W \\oplus W^\\perp. This implies that V is completely reducible. \\square\n\n\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.6. Unitary representations. Another proof of Maschke's theorem for complex representations\u0009Unitary representations are completely reducible","header":"Unitary representations are completely reducible","id":"/4___-Representations-of-finite-groups___-Basic-results/4___6___-Unitary-representations___-Another-proof-of-Maschke___s-theorem-for-complex-representations/Unitary-representations-are-completely-reducible/#Chapter4___Theorem4___6___3"},"/4___-Representations-of-finite-groups___-Basic-results/4___7___-Orthogonality-of-matrix-elements/Section-4___7___-Orthogonality-of-matrix-elements/#Chapter4___Introduction_4___7___heading-1":{"contents":"Let V be an irreducible representation of a finite group G, and let v_1, v_2, \\ldots, v_n be an orthonormal basis of V under the invariant Hermitian form. The matrix elements of V are t^V_{ij}(x) = (\\rho_V(x)v_i, v_j).\n\n","context":"Introduction to Representation Theory\u00094. Representations of finite groups: Basic results\u00094.7. Orthogonality of matrix elements\u0009Section 4.7: Orthogonality of matrix elements\u0009Section 4.7: Orthogonality of matrix elements","header":"4.7. Orthogonality of matrix elements","id":"/4___-Representations-of-finite-groups___-Basic-results/4___7___-Orthogonality-of-matrix-elements/Section-4___7___-Orthogonality-of-matrix-elements/#Chapter4___Introduction_4___7___heading-1"},"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Observation-that-number-of-indecomposables-is-orientation-independent/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___3___-Indecomposable-representations-of-the-quiver-___D_4___--Observation-that-number-of-indecomposables-is-orientation-independent--Observation-that-number-of-indecomposables-is-orientation-independent--Formalization--Supporting-declarations":{"contents":"Every indecomposable representation is equivalent to a standard representation for a unique admissible dimension.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Discussion_after_Example6.3.1; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Example6.3.1; role=primary]\n\nUnder the given matrix and quiver hypotheses, the predicate on integer vectors has finitely many solutions, holds for the componentwise finrank vector of every object with the stated property, and classifies such objects by that vector up to the specified relation.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Discussion_after_Example6.3.1; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter6/Theorem6.5.2; role=primary]\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.3. Indecomposable representations of the quiver $D_4$\u0009Observation that number of indecomposables is orientation-independent\u0009Observation that number of indecomposables is orientation-independent\u0009Formalization","header":"Supporting declarations","id":"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Observation-that-number-of-indecomposables-is-orientation-independent/#Introduction-to-Representation-Theory--6___-Quiver-representations--6___3___-Indecomposable-representations-of-the-quiver-___D_4___--Observation-that-number-of-indecomposables-is-orientation-independent--Observation-that-number-of-indecomposables-is-orientation-independent--Formalization--Supporting-declarations"},"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Section-7___4___-Equivalence-of-categories/#Chapter7___Introduction_7___4":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.4. Equivalence of categories\u0009Section 7.4: Equivalence of categories","header":"Section 7.4: Equivalence of categories","id":"/7___-Introduction-to-categories/7___4___-Equivalence-of-categories/Section-7___4___-Equivalence-of-categories/#Chapter7___Introduction_7___4"},"/7___-Introduction-to-categories/7___5___-Representable-functors/Representable-functors-for-enriched-categories/#Chapter7___Remark7___5___2":{"contents":"Remark 7.5.2. In a similar way, if a category \\mathcal{C} is enriched over another category \\mathcal{D} (say, the category of abelian groups or vector spaces), one can define the notion of a representable functor from \\mathcal{C} to \\mathcal{D}.\n\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.5. Representable functors\u0009Representable functors for enriched categories","header":"Representable functors for enriched categories","id":"/7___-Introduction-to-categories/7___5___-Representable-functors/Representable-functors-for-enriched-categories/#Chapter7___Remark7___5___2"},"/7___-Introduction-to-categories/7___8___-Complexes-and-cohomology/Exact-sequences-of-vector-spaces-split/#Chapter7___Exercise7___8___4":{"contents":"Exercise 7.8.4. Show that any exact sequence of vector spaces is isomorphic to a direct sum of complexes of the form\n\n0 \\to V \\to V \\to 0,\n\nwhere V stands at the places i and i + 1 and the map V \\to V is the identity (in particular, any short exact sequence of vector spaces is split). Is this true in the category of abelian groups?\n\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.8. Complexes and cohomology\u0009Exact sequences of vector spaces split","header":"Exact sequences of vector spaces split","id":"/7___-Introduction-to-categories/7___8___-Complexes-and-cohomology/Exact-sequences-of-vector-spaces-split/#Chapter7___Exercise7___8___4"},"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/Section-8___1___-Projective-and-injective-modules/#Introduction-to-Representation-Theory--8___-Homological-algebra--8___1___-Projective-and-injective-modules--Section-8___1___-Projective-and-injective-modules":{"contents":"\n\n","context":"Introduction to Representation Theory\u00098. Homological algebra\u00098.1. Projective and injective modules","header":"Section 8.1: Projective and injective modules","id":"/8___-Homological-algebra/8___1___-Projective-and-injective-modules/Section-8___1___-Projective-and-injective-modules/#Introduction-to-Representation-Theory--8___-Homological-algebra--8___1___-Projective-and-injective-modules--Section-8___1___-Projective-and-injective-modules"}});